import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import * as path from 'node:path';
import { sanitizedDeltaOf } from '../intelligence/index.js';

/*
 * Regression fixture for discovery f-e3a3f17f095c20582322485d: The fluid Configure Event Mapping page re-saves every row on Save
 * Generated by tools/intelligence/engineering-task.mts. It proves the captures still
 * show what the finding recorded; extend it to replay the writer the finding informs.
 */

const RESULTS = path.join('tools', 'corpus', 'save-protocol', 'results');
const EXPECTED = [
  {
    "capture": "em04-fluid-add-record",
    "delta": {
      "tables": [
        {
          "table": "PSADSTRACKING",
          "inserted": 1,
          "deleted": 0,
          "updated": 2
        },
        {
          "table": "PSPTCSSRVCONF",
          "inserted": 2,
          "deleted": 1,
          "updated": 0
        },
        {
          "table": "PSPTCS_MAPFLDS",
          "inserted": 2,
          "deleted": 1,
          "updated": 0
        }
      ],
      "counters": {
        "SCNFM": 2,
        "SYS": 2
      }
    }
  },
  {
    "capture": "em05-fluid-page-record-edit",
    "delta": {
      "tables": [
        {
          "table": "PSADSTRACKING",
          "inserted": 2,
          "deleted": 0,
          "updated": 3
        },
        {
          "table": "PSPTCSSRVCONF",
          "inserted": 3,
          "deleted": 1,
          "updated": 1
        },
        {
          "table": "PSPTCS_MAPFLDS",
          "inserted": 2,
          "deleted": 2,
          "updated": 0
        }
      ],
      "counters": {
        "SCNFM": 4,
        "SYS": 4
      }
    }
  },
  {
    "capture": "em06-fluid-delete-row",
    "delta": {
      "tables": [
        {
          "table": "PSADSTRACKING",
          "inserted": 0,
          "deleted": 0,
          "updated": 5
        },
        {
          "table": "PSPTCSSRVCNFDEL",
          "inserted": 1,
          "deleted": 0,
          "updated": 0
        },
        {
          "table": "PSPTCSSRVCONF",
          "inserted": 2,
          "deleted": 3,
          "updated": 1
        },
        {
          "table": "PSPTCS_MAPFLDS",
          "inserted": 2,
          "deleted": 2,
          "updated": 0
        }
      ],
      "counters": {
        "SCNFM": 4,
        "SYS": 4
      }
    }
  }
];

for (const { capture, delta } of EXPECTED) {
  test(`f-e3a3f17f095c20582322485d: capture ${capture} still shows the recorded rows and counters`, { skip: !existsSync(path.join(RESULTS, capture, 'delta.json')) && 'capture not present' }, () => {
    assert.deepEqual(sanitizedDeltaOf(JSON.parse(readFileSync(path.join(RESULTS, capture, 'delta.json'), 'utf8'))), delta);
  });
}
